components.css:
.ds-topbar{display:flex;min-height:82px;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(239,238,230,.09)}
.ds-brand{display:inline-flex;align-items:center;gap:10px;color:#ece9df;font:16px Georgia,"Times New Roman",serif;letter-spacing:-.025em;text-decoration:none}
.ds-brand-mark{display:grid;width:30px;height:30px;place-items:center;border:1px solid rgba(212,169,119,.25);border-radius:50%;background:rgba(212,169,119,.07);color:#d7ad7b;font:12px Arial,sans-serif}
.ds-brand-dot{color:#d4a977}
.ds-actions{display:flex;align-items:center;gap:6px}
.ds-nav-button{border:0;background:transparent;color:#c7c8bf;font:12px Arial,sans-serif}
.ds-nav-button{min-height:34px;padding:7px 8px;border:0;border-radius:9px;background:transparent;color:#c7c8bf;font:12px Arial,sans-serif;cursor:pointer;transition:background-color .2s ease,color .2s ease}
.ds-nav-button:hover{background:rgba(255,255,255,.07);color:#fff}
.ds-button{min-height:36px;padding:6px 12px;border:1px solid #d4a977;border-radius:12px;background:#d4a977;color:#171915;font:500 12px Arial,sans-serif;cursor:pointer;transition:background-color .2s ease,border-color .2s ease}
.ds-button:hover{border-color:#e2bb8d;background:#e2bb8d}
.ds-nav-button:focus-visible,.ds-button:focus-visible{outline:2px solid #e7bd8e;outline-offset:2px}
.ds-brand-mark svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}

.ds-card{display:flex;min-width:152px;height:27rem;overflow:hidden;border:1px solid rgba(236,234,225,.12);border-radius:21px;background:#20231d;box-shadow:0 17px 44px rgba(0,0,0,.16)}
.ds-card-cover{display:flex;width:100%;flex:1;flex-direction:column;justify-content:space-between;padding:18px;border:0;border-radius:20px;background:radial-gradient(ellipse at 18% 5%,rgba(184,143,95,.23),transparent 53%),linear-gradient(135deg,#34382f 0%,#252820 56%,#181b17 100%);color:#f4f1e9;text-align:left}
.ds-card-top{display:flex;align-items:center;justify-content:space-between;gap:8px}
.ds-card-category,.ds-card-status{display:inline-flex;min-height:26px;align-items:center;padding:0 9px;border:1px solid rgba(255,255,255,.09);border-radius:999px;background:rgba(16,18,16,.46);color:#e3c79e;font:10px Arial,sans-serif;backdrop-filter:blur(12px)}
.ds-card-bottom{display:flex;flex-direction:column;align-items:flex-start;gap:8px}
.ds-card-title{color:#f3f0e8;font:400 clamp(17px,1.7vw,24px)/1.1 Georgia,"Times New Roman",serif;letter-spacing:-.035em}
.ds-card-description{max-width:540px;color:rgba(238,236,226,.79);font:12px/1.55 Arial,sans-serif}
.ds-card:hover .ds-card-cover{filter:saturate(1.08) brightness(1.05)}
.ds-card.is-expanded{border-color:rgba(215,183,142,.4);box-shadow:0 23px 54px rgba(0,0,0,.3),0 0 0 1px rgba(215,183,142,.06)}
.ds-status-planned{color:#e3c79e}.ds-status-progress{color:#c2dce4}.ds-status-done{color:#c6dfc1}
.ds-card-cover:focus-visible{outline:2px solid #e7bd8e;outline-offset:-5px}

.ds-dialog{width:min(650px,calc(100% - 30px));max-height:90vh;padding:0;overflow:auto;border:1px solid rgba(232,216,191,.14);border-radius:22px;background:#1a1d19;color:#eeece5;box-shadow:0 30px 110px rgba(0,0,0,.58)}
.ds-dialog::backdrop{background:rgba(6,8,6,.77);backdrop-filter:blur(7px)}
.ds-dialog-content{padding:25px 27px 23px}
.ds-eyebrow{color:#a79374;font:700 8px Arial,sans-serif;letter-spacing:.17em}
.ds-dialog h2{margin:7px 0 22px;font:400 27px Georgia,"Times New Roman",serif;letter-spacing:-.04em}
.ds-field{display:flex;flex-direction:column;gap:7px;color:#d4d3ca;font:11px Arial,sans-serif}
.ds-field input{min-height:42px;padding:10px 12px;border:1px solid rgba(237,234,224,.11);border-radius:10px;background:rgba(255,255,255,.035);color:#eceae2;font:12px Arial,sans-serif}
.ds-field input:focus{border-color:rgba(222,184,136,.55);outline:2px solid #e7bd8e;outline-offset:2px}
.ds-dialog .ds-button{margin-top:18px}
.ds-button{display:inline-flex;min-height:44px;align-items:center;justify-content:center;padding:10px 16px;border:1px solid #d4a977;border-radius:12px;background:#d4a977;color:#171915;font:500 14px Arial,sans-serif;cursor:pointer;transition:background-color .2s ease,border-color .2s ease}
.ds-button:hover{border-color:#e2bb8d;background:#e2bb8d}
.ds-button:focus-visible{outline:0;box-shadow:0 0 0 2px #121411,0 0 0 4px #e7bd8e}

.ds-empty{display:flex;min-height:363px;flex-direction:column;align-items:center;justify-content:center;padding:37px 20px 44px;border:1px dashed rgba(225,218,203,.17);border-radius:21px;background:radial-gradient(ellipse at 50% 40%,rgba(109,104,82,.11),transparent 47%),rgba(255,255,255,.012);text-align:center}
.ds-empty-icon{display:grid;width:54px;height:54px;place-items:center;margin:0 0 19px;border:1px solid rgba(219,183,136,.34);border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(216,182,136,.23),rgba(216,182,136,.04));color:#e2c49d;box-shadow:0 0 35px rgba(207,170,123,.12);font:24px Georgia,serif}
.ds-empty-eyebrow{margin:0 0 9px;color:#9f947e;font:700 8px Arial,sans-serif;letter-spacing:.16em}
.ds-empty h3{margin:0;color:#eeece4;font:400 28px Georgia,"Times New Roman",serif;letter-spacing:-.04em}
.ds-empty p{max-width:485px;margin:9px 0 19px;color:#92968b;font:12px/1.7 Arial,sans-serif}
.ds-empty .ds-button{min-height:42px}
.ds-empty-icon svg{width:24px;height:24px;fill:none;stroke:currentColor;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}
.ds-button{display:inline-flex;min-height:44px;align-items:center;justify-content:center;padding:10px 16px;border:1px solid #d4a977;border-radius:12px;background:#d4a977;color:#171915;font:500 14px Arial,sans-serif;cursor:pointer;transition:background-color .2s ease,border-color .2s ease}
.ds-button:hover{border-color:#e2bb8d;background:#e2bb8d}
.ds-button:focus-visible{outline:0;box-shadow:0 0 0 2px #121411,0 0 0 4px #e7bd8e}
